class Solution:

	def rotation(self, N):
		from collections import deque
		D = deque(range(1, N + 1))
		ans = [0] * N
		p = []
		for i in range(1, N):
			D.rotate(-i)
			p.append(D.popleft())
		p.append(D.pop())
		for (i, v) in enumerate(p, 1):
			ans[v - 1] = i
		return ans
